def caesar_cipher(s, shift):
    def shift_char(c):
        if c.isalpha():
            base = ord('a') if c.islower() else ord('A')
            return chr((ord(c) - base + shift) % 26 + base)
        else:
            return c
    return ''.join(shift_char(c) for c in s)
