def longest_increasing_subsequence_length(nums):
    if not nums:
        return 0
    n = len(nums)
    tails = []
    for num in nums:
        import bisect
        idx = bisect.bisect_left(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num
    return len(tails)
