def fibonacci_memo(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    memo = {}
    def fib(k):
        if k in memo:
            return memo[k]
        if k == 0:
            memo[k] = 0
        elif k == 1:
            memo[k] = 1
        else:
            memo[k] = fib(k - 1) + fib(k - 2)
        return memo[k]
    return fib(n)
```

